llm.prompt_data_template:
Trial: {case_name} ({court} {case_number}).

The transcript, one JSON string per page, in order:
{pages}

starlark.code:
def transform(row):
    pages = row["pages"]
    cut = row["deliberations_begin"]
    if cut == None:
        refuse("%s: no quote marks where deliberations began, so the transcript cannot be cut" % row["case_name"])
    at = find_page(pages, cut, row["case_name"])
    leaked = {}
    for leak in row["outcome_leaks"]:
        leaked[key(leak)] = True
    if key(cut) in leaked:
        refuse("%s: an outcome leak sits on the page where deliberations began, page %d" % (row["case_name"], cut["locator"]["page"]))
    kept = [page for page in pages[:at] if key(page) not in leaked]
    return dict(row, transcript=kept + [cut_page(pages[at], cut)], pages_kept=len(kept) + 1,
                pages_removed=len(pages) - at - 1, leak_pages_removed=at - len(kept))


def key(span):
    return "%s:%d" % (span["source_id"], span["locator"]["page"])


def find_page(pages, cut, case_name):
    for i in range(len(pages)):
        if key(pages[i]) == key(cut):
            return i
    refuse("%s: the deliberations quote sits on no page of the transcript" % case_name)


def cut_page(page, cut):
    locator = page["locator"]
    end = cut["locator"]["end"]
    return {"source_id": page["source_id"], "source_sha256": page["source_sha256"],
            "locator": {"kind": locator["kind"], "page": locator["page"], "start": locator["start"], "end": end},
            "quote": page["quote"][:end - locator["start"]], "prefix": None, "suffix": None}

def transform(row):
    if row["verdicts"] == None:
        return dict(row, counts_compared=0, counts_agreeing=0, agreement="no_model_verdict",
                    disagreements=["The judging model gave no valid reply; judge_verdict's row error says why"])
    jury = by_count(row["jury_verdicts"])
    model = by_count(row["verdicts"])
    both = sorted([count for count in jury if count in model])
    agreeing = [count for count in both if jury[count] == model[count]]
    return dict(row, counts_compared=len(both), counts_agreeing=len(agreeing),
                agreement=judge_agreement(jury, model, both, agreeing),
                disagreements=list_disagreements(jury, model))


def by_count(verdicts):
    found = {}
    for verdict in verdicts:
        found[verdict["count"]] = verdict["verdict"]
    return found


def judge_agreement(jury, model, both, agreeing):
    if not both:
        return "no_counts_compared"
    if len(agreeing) == len(jury) and len(model) == len(jury):
        return "agree"
    if not agreeing:
        return "disagree"
    return "partial"


def list_disagreements(jury, model):
    lines = []
    for count in sorted(jury):
        if count not in model:
            lines.append("Count %d: the jury found %s; the model gave no verdict" % (count, jury[count]))
        elif jury[count] != model[count]:
            lines.append("Count %d: the jury found %s; the model found %s" % (count, jury[count], model[count]))
    for count in sorted(model):
        if count not in jury:
            lines.append("Count %d: the model found %s; the jury's verdict names no such count" % (count, model[count]))
    return lines

llm.prompt_data_template:
Case: {case_name} ({court} {case_number}).

The judgment, one JSON string per page:
{record_pages}

starlark.code:
def transform(row):
    if row["record_verdicts"] == None:
        return dict(row, record_agreement="no_record",
                    record_notes=["No judgment for this trial is in the mirror, so the transcript reading goes unchecked"])
    read = by_count(row["jury_verdicts"])
    record = by_count(row["record_verdicts"])
    notes = []
    for count in sorted(read):
        if count not in record:
            notes.append("Count %d: the transcript reading says %s; the judgment names no such count" % (count, read[count]))
        elif read[count] != record[count]:
            notes.append("Count %d: the transcript reading says %s; the judgment says %s" % (count, read[count], record[count]))
    for count in sorted(record):
        if count not in read:
            notes.append("Count %d: the judgment says %s; the transcript reading names no such count" % (count, record[count]))
    return dict(row, record_agreement="agree" if not notes else "disagree", record_notes=notes)


def by_count(verdicts):
    found = {}
    for verdict in verdicts:
        found[verdict["count"]] = verdict["verdict"]
    return found
